def format_bytes(n):
    """Returns a human-readable size string (e.g., '1.5 KB')."""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return f"{n:.2f} {unit}"
        n /= 1024.0
    return f"{n:.2f} PB"'
